<script setup>
import { onMounted, ref, watch } from "vue";
import { call, __ } from "../api";

const props = defineProps({ name: String });
const state = ref("loading");
const error = ref("");
const data = ref(null);
async function load() { state.value = "loading"; try { data.value = await call("an_truck_portal.api.warranty.get_claim", { name: props.name }); state.value = "ready"; } catch (e) { error.value = e.message; state.value = "error"; } }
onMounted(load); watch(() => props.name, load);
function date(value) { return value ? new Intl.DateTimeFormat(document.documentElement.lang || "en", { dateStyle: "medium" }).format(new Date(`${String(value).slice(0,10)}T00:00:00`)) : "—"; }
function money(value) { if (value === null || value === undefined || value === "") return "—"; try { return new Intl.NumberFormat(document.documentElement.lang || "en", { style: "currency", currency: data.value.claim.currency || "SAR" }).format(Number(value)); } catch { return value; } }
</script>

<template>
	<div class="page warranty-page">
		<div v-if="state === 'loading'" class="panel empty">{{ __("Loading…") }}</div><div v-else-if="state === 'error'" class="panel empty error">{{ error }}</div>
		<template v-else>
			<header class="panel workspace-header"><div><p class="eyebrow">{{ __("Warranty Claim") }}</p><h1><bdi>{{ data.claim.name }}</bdi></h1><p><bdi>{{ data.claim.vin }}</bdi></p></div><div class="page-actions"><router-link class="button secondary" to="/warranty-claims">{{ __("Back to Claims") }}</router-link><router-link v-if="data.claim.vehicle_warranty" class="button" :to="`/warranties/${encodeURIComponent(data.claim.vehicle_warranty)}`">{{ __("Open Warranty") }}</router-link></div></header>
			<section class="panel section-card"><div class="section-head"><h2>{{ __("Claim Summary") }}</h2><span class="badge">{{ __(data.claim.status) }}</span></div><div class="detail"><div><small>{{ __("VIN") }}</small><bdi><b>{{ data.claim.vin }}</b></bdi></div><div><small>{{ __("Vehicle") }}</small><b>{{ data.claim.vehicle_master || '—' }}</b></div><div><small>{{ __("Warranty") }}</small><b>{{ data.claim.vehicle_warranty }}</b></div><div><small>{{ __("Customer") }}</small><b>{{ data.claim.customer_name || data.claim.customer }}</b></div><div><small>{{ __("Provider") }}</small><b>{{ data.claim.provider }}</b></div><div><small>{{ __("Provider Branch") }}</small><b>{{ data.claim.provider_branch || '—' }}</b></div><div><small>{{ __("Claim Date") }}</small><b>{{ date(data.claim.claim_date) }}</b></div><div><small>{{ __("Warranty Eligibility") }}</small><b>{{ __(data.claim.eligibility || 'Pending') }}</b></div><div><small>{{ __("Provider Decision") }}</small><b>{{ __(data.claim.provider_decision || 'Pending') }}</b></div><div><small>{{ __("Coverage Decision") }}</small><b>{{ __(data.claim.coverage_decision || 'Pending') }}</b></div><div><small>{{ __("Approval Date") }}</small><b>{{ date(data.claim.approval_date) }}</b></div></div></section>
			<div class="columns warranty-narrative"><section class="panel section-card"><h2>{{ __("Complaint") }}</h2><p class="long-text">{{ data.claim.complaint || '—' }}</p></section><section class="panel section-card"><h2>{{ __("Inspection") }}</h2><div class="detail"><div><small>{{ __("Inspection Date") }}</small><b>{{ date(data.claim.inspection_date) }}</b></div><div><small>{{ __("Technician") }}</small><b>{{ data.claim.technician || '—' }}</b></div></div><p class="long-text">{{ data.claim.inspection || '—' }}</p></section><section class="panel section-card"><h2>{{ __("Diagnosis") }}</h2><p class="long-text">{{ data.claim.diagnosis || '—' }}</p><p class="long-text"><strong>{{ __("Root Cause") }}:</strong> {{ data.claim.root_cause || '—' }}</p></section><section class="panel section-card"><h2>{{ __("Decision") }}</h2><p class="long-text">{{ data.claim.decision_reason || data.claim.provider_reason || '—' }}</p></section></div>
			<section class="panel section-card"><div class="section-head"><h2>{{ __("Costs") }}</h2></div><div class="detail"><div><small>{{ __("Total Repair Cost") }}</small><b>{{ money(data.claim.total_repair_cost) }}</b></div><div><small>{{ __("Warranty Covered Amount") }}</small><b>{{ money(data.claim.warranty_covered_amount) }}</b></div><div><small>{{ __("Customer Payable") }}</small><b>{{ money(data.claim.customer_payable_amount) }}</b></div><div><small>{{ __("Provider Claim Amount") }}</small><b>{{ money(data.claim.provider_claim_amount) }}</b></div><div v-if="data.claim.approved_provider_amount !== null"><small>{{ __("Approved Provider Amount") }}</small><b>{{ money(data.claim.approved_provider_amount) }}</b></div></div></section>
			<section class="panel section-card"><div class="section-head"><h2>{{ __("Parts") }}</h2><span class="badge neutral">{{ data.parts.length }}</span></div><div v-if="data.parts.length" class="table-wrap"><table><thead><tr><th>{{ __("Category") }}</th><th>{{ __("Part") }}</th><th>{{ __("Description") }}</th><th>{{ __("Quantity") }}</th><th>{{ __("Total") }}</th><th>{{ __("Coverage") }}</th><th>{{ __("Covered Amount") }}</th><th>{{ __("Customer Payable") }}</th></tr></thead><tbody><tr v-for="(row,index) in data.parts" :key="index"><td>{{ row.category }}</td><td>{{ row.item || row.part_number || '—' }}</td><td class="wrap-cell">{{ row.description }}</td><td>{{ row.qty }} {{ row.uom || '' }}</td><td>{{ money(row.total) }}</td><td>{{ __(row.coverage_status) }}</td><td>{{ money(row.covered_amount) }}</td><td>{{ money(row.customer_payable) }}</td></tr></tbody></table></div><div v-else class="empty">{{ __("No parts recorded.") }}</div></section>
			<section class="panel section-card"><div class="section-head"><h2>{{ __("Labour / Services") }}</h2><span class="badge neutral">{{ data.services.length }}</span></div><div v-if="data.services.length" class="table-wrap"><table><thead><tr><th>{{ __("Category") }}</th><th>{{ __("Service") }}</th><th>{{ __("Description") }}</th><th>{{ __("Hours") }}</th><th>{{ __("Total") }}</th><th>{{ __("Coverage") }}</th><th>{{ __("Covered Amount") }}</th><th>{{ __("Customer Payable") }}</th></tr></thead><tbody><tr v-for="(row,index) in data.services" :key="index"><td>{{ row.category }}</td><td>{{ row.service_type }}</td><td class="wrap-cell">{{ row.description }}</td><td>{{ row.hours }}</td><td>{{ money(row.total) }}</td><td>{{ __(row.coverage_status) }}</td><td>{{ money(row.covered_amount) }}</td><td>{{ money(row.customer_payable) }}</td></tr></tbody></table></div><div v-else class="empty">{{ __("No services recorded.") }}</div></section>
			<section class="panel section-card"><div class="section-head"><h2>{{ __("Documents") }}</h2><span class="badge neutral">{{ data.documents.length }}</span></div><div v-if="data.documents.length" class="document-list warranty-documents"><div v-for="(row,index) in data.documents" :key="index"><span>{{ __(row.type) }}</span><a :href="row.file" target="_blank" rel="noopener">{{ __("Open document") }}</a><small>{{ row.invoice_number || '' }} <template v-if="row.total">· {{ money(row.total) }}</template></small></div></div><div v-else class="empty">{{ __("No documents attached.") }}</div></section>
		</template>
	</div>
</template>
